#!/usr/bin/env bash
# Evaluation videos for the policies trained with scripts/train_all_mjlab.sh: one
# `eval_mjlab_policy.py` command per training line, in the same order and grouping.
# The lines are meant to be copy-pasted one at a time (repo root as working directory);
# executed as-is, the script runs all uncommented lines one after another:
#   bash scripts/eval_all_mjlab.sh
#   nohup bash scripts/eval_all_mjlab.sh > eval_all.log 2>&1 &   # survives SSH drops
# --checkpoint reads the run directory from nohup_<env_id>.out (written by the training
# script) and the newest model_<iter>.pt in it is used. For runs started differently, pass
# the run directory yourself. All videos go to baselines/evals/ (created if missing) as
# eval_<env_id>.mp4. The camera and grid settings suit the arm-reach tasks, so adjust
# --distance/--azimuth/--env-spacing for other bodies. Rendering needs an offscreen GL
# backend (EGL by default here).
export MUJOCO_GL="${MUJOCO_GL:-egl}"
mkdir -p baselines/evals

# ---- Implemented mjlab twins ----
# -- Pose (new tasks/ package) --
